"""Render the general rank-one-complement exclusion, including N17 AC6."""
from pathlib import Path
import html,json,re
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1]
def m(x,display=True):
 tag='div' if display else 'span';return f'<{tag} class="math" data-display="{str(display).lower()}" data-tex="{html.escape(x,quote=True)}"></{tag}>'
def links(items):return '<div class="proof-links">'+''.join(f'<a href="{html.escape(u,quote=True)}">{t} ↗</a>' for u,t in items)+'</div>'
def main():
 assert json.loads((HERE/'verification.json').read_text())['passed']
 css=re.search(r'<style>(.*?)</style>',(ROOT/'research/t2-qec-upper/index.html').read_text(),re.S).group(1)+'\n.math{max-width:100%;overflow-x:auto}.proof-step{border-left:3px solid #b8c9bd;padding-left:1.2rem;margin:2rem 0}.badge{color:#1c6253;text-transform:uppercase;font-size:.8rem;letter-spacing:.08em}'
 b='<p class="eyebrow">Anticoherent states and subspaces · Rank-one complement</p><a href="../../index.html#n=17&t=6">← Catalogue entry</a><h1>A short proof excluding sixth order at seventeen qubits</h1>'
 b+='<div class="result"><span class="badge">Analytical proof · arbitrary complex states</span>'+m(r'\boxed{K(17,6)=0.}')+'<p>Fifteen orthogonal tensor images would leave a one-dimensional complement. That complement would be an anticoherent pure state too, at a size forbidden by the same tensor count.</p></div>'
 b+='<section><h2>The argument at seventeen qubits</h2><div class="proof-step"><h3>1. Fifteen orthogonal images</h3><p>Suppose a normalized sixth-order AC state exists in '+m(r'V_{17/2}',False)+'. Choose Hilbert–Schmidt orthonormal rectangular spin tensors '+m(r'A_{\ell q}:V_{17/2}\longrightarrow V_{15/2}',False)+', taking every component of ranks '+m(r'\ell=1,2,3',False)+'. There are '+m(r'3+5+7=15',False)+' tensors. Each product '+m(r'A_{\ell q}^{\dagger}A_{\ell^{\prime}q^{\prime}}',False)+' has ranks at most six, so anticoherence gives</p>'+m(r'\langle\psi|A_{\ell q}^{\dagger}A_{\ell^{\prime}q^{\prime}}|\psi\rangle=\frac{\delta_{\ell\ell^{\prime}}\delta_{qq^{\prime}}}{18}.')+'<p>Thus the fifteen vectors '+m(r'\sqrt{18}\,A_{\ell q}|\psi\rangle',False)+' are orthonormal in a sixteen-dimensional output space.</p></div>'
 b+='<div class="proof-step"><h3>2. The complement is pure and sixth-order AC</h3><p>The operator</p>'+m(r'Q=18\sum_{\ell=1}^{3}\sum_{q=-\ell}^{\ell}A_{\ell q}|\psi\rangle\langle\psi|A_{\ell q}^{\dagger}')+'<p>is a rank-fifteen orthogonal projector. Consequently</p>'+m(r'I_{16}-Q=|\phi\rangle\langle\phi|.')+'<p>Summing complete tensor multiplets makes the map rotation covariant. It maps each irreducible operator rank into the same rank, so the vanishing multipoles through rank six are preserved. Subtracting from the identity therefore makes '+m(r'|\phi\rangle',False)+' a pure sixth-order AC state on fifteen qubits.</p></div>'
 b+='<div class="proof-step"><h3>3. Dimension counting gives a contradiction</h3><p>Apply the same rank-one through rank-three construction to '+m(r'|\phi\rangle',False)+', now mapping '+m(r'V_{15/2}\to V_{13/2}',False)+'. It would produce fifteen mutually orthogonal nonzero vectors in dimension fourteen:</p>'+m(r'15\le14.')+'<p>This contradiction excludes the original seventeen-qubit state. No numerical optimization or finite certificate is needed for this argument.</p></div></section>'
 b+='<section><h2>A general family of exclusions</h2><p>Let '+m(r'D=(r+1)^2',False)+' and suppose there is a pure '+m(r'2r',False)+'-AC state on '+m(r'N=D+1',False)+' qubits. Rectangular ranks one through '+m(r'r',False)+' give</p>'+m(r'\sum_{\ell=1}^{r}(2\ell+1)=r(r+2)=D-1')+'<p>orthogonal images in dimension '+m(r'N-1=D',False)+'. Their rank-one complement is a pure '+m(r'2r',False)+'-AC state on '+m(r'D-1',False)+' qubits. Repeating the tensor count would require '+m(r'D-1\le D-2',False)+'. Hence</p>'+m(r'\boxed{K((r+1)^2+1,2r)=0\quad\text{for every integer }r\ge1.}')+'<p>The first excluded pairs are '+m(r'(N,t)=(5,2),(10,4),(17,6),(26,8),\ldots',False)+'. The LaTeX proof also states the general covariant rank-one-complement lemma.</p>'+links([('proof.tex','Complete analytical proof'),('verify_channel.py','Exact tensor and channel verifier'),('verification.json','Verification report')])+'</section>'
 b+='<section><h2>The stronger result at fifth order</h2><p>An independent three-copy partial-transpose certificate also excludes fifth order at seventeen qubits. Combined with the existing exact fourth-order witness, it gives</p>'+m(r'\boxed{t_{\max}(17)=4,\qquad K(17,t)=0\quad(t\ge5).}')+links([('../n17-t5/index.html','Fifth-order certificate'),('../n17-t4/index.html','Analytical fourth-order state')])+'</section>'
 head='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>N=17: sixth-order rank-one-complement exclusion</title><link rel="stylesheet" href="../../vendor/katex/katex.min.css"><script defer src="../../vendor/katex/katex.min.js"></script><style>'+css+'</style><script>document.addEventListener("DOMContentLoaded",()=>document.querySelectorAll("[data-tex]").forEach(el=>{if(window.katex)el.innerHTML=katex.renderToString(el.dataset.tex,{displayMode:el.dataset.display==="true",throwOnError:false,strict:"ignore",trust:false});}));</script></head><body><main>'
 (HERE/'index.html').write_text(head+b+'</main></body></html>\n')
if __name__=='__main__':main()
